#include <logdepthbuf_pars_fragment>
#include <clipping_planes_pars_fragment>
uniform float pxmm;
uniform float kind;
uniform float flip;
uniform float tag;
uniform vec3 ink;
float band(float d, float step) {
  float f = abs(fract(d / step + 0.5) - 0.5) * step * pxmm,
    w = max(1.0, 0.18 * pxmm);
  return clamp(w * 0.5 + 0.5 - f, 0.0, 1.0);
}
void main() {
  #include <clipping_planes_fragment>
  #include <logdepthbuf_fragment>
  vec2 p = gl_FragCoord.xy / pxmm;
  float a = (p.x * flip + p.y) * 0.70710678,
    b = (p.x * flip - p.y) * 0.70710678,
    k = floor(kind + 0.5),
    v = 0.0;
  if (k < 0.5) v = band(a, 2.0); // общая (материал не узнан)
  else if (k < 1.5) v = band(a, 1.2); // металл — частая
  else if (k < 2.5) v = max(band(a, 2.5), band(b, 2.5)); // ДСП — сетка
  else if (k < 3.5) v = max(band(a, 1.6), band(b, 1.6)); // МДФ — сетка чаще
  else if (k < 4.5) v = max(band(a, 1.0), band(b, 1.0)); // ХДФ, ДВП — сетка частая
  else if (k < 5.5) v = band(p.y + 0.45 * sin(p.x * 1.7), 1.6); // массив — волокна
  else if (k < 6.5) v = max(band(p.y + 0.35 * sin(p.x * 2.2), 1.0), band(a, 3.0)); // фанера — слои
  else if (k < 7.5) v = band(a, 2.0) * (mod(floor(a / 2.0 + 0.5), 2.0) < 0.5 ? 1.0 : step(0.5, fract(b / 1.6))); // камень — сплошная через штриховую
  else if (k < 8.5) v = band(a, 0.8) * step(fract(a / 6.0), 0.3) * step(fract(b / 5.0), 0.45); // стекло — группы штрихов
  else v = max(band(a, 2.0), band(b, 2.0) * step(0.5, fract(a / 1.2))); // пластик — сплошная и штриховая
  // альфа — метка среза (250…253 — деталь по id): по ней контур и узкие сечения
  gl_FragColor = vec4(mix(vec3(1.0), ink, v), tag);
